def cmp_semver(a, b):
    def parse(v):
        v = v.split('+', 1)[0]
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, None
        major, minor, patch = map(int, core.split('.'))
        if pre is not None:
            pre_ids = []
            for p in pre.split('.'):
                if p.isdigit():
                    pre_ids.append((0, int(p)))
                else:
                    pre_ids.append((1, p))
        else:
            pre_ids = None
        return major, minor, patch, pre_ids

    am, an, ap, apre = parse(a)
    bm, bn, bp, bpre = parse(b)

    for x, y in [(am, bm), (an, bn), (ap, bp)]:
        if x < y: return -1
        if x > y: return 1

    if apre is None and bpre is None:
        return 0
    if apre is None:
        return 1
    if bpre is None:
        return -1

    for i in range(max(len(apre), len(bpre))):
        if i >= len(apre):
            return -1
        if i >= len(bpre):
            return 1
        a_type, a_val = apre[i]
        b_type, b_val = bpre[i]
        if a_type != b_type:
            return -1 if a_type < b_type else 1
        if a_val < b_val:
            return -1
        if a_val > b_val:
            return 1

    return 0
