        return False

    is_dir = pattern.endswith('/')
    pattern = pattern.rstrip('/')
    if not pattern:
        return False

    is_anchored = pattern.startswith('/')
    pattern = pattern.lstrip('/')

    if '/' in pattern and not pattern.startswith('**/'):
        is_anchored = True

    regex = ''
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '*':
            if i + 1 < n and pattern[i+1] == '*':
                if i == 0:
                    if i + 2 < n and pattern[i+2] == '/':
                        regex += '(.*/)?'
                        i += 3
                    else:
                        regex += '.*'
                        i += 2
                else:
                    if pattern[i-1] == '/':
                        if i + 2 < n and pattern[i+2] == '/':
                            regex += '(/.*)?'
                            i += 2
                        else:
                            regex += '(/.*)?'
                            i += 2
                    else:
                        regex += '[^/]*'
                        i += 2
            else:
                regex += '[^/]*'
                i += 1
        elif c == '?':
            regex += '[^/]'
            i += 1
        elif c == '[':
            j = i + 1
            if j < n and pattern[j] == '!':
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j >= n:
                regex += re.escape(c)
                i += 1
            else:
                cls = pattern[i+1:j]
                if cls.startswith('!'):
                    cls = '^' + cls[1:]
                regex += '[' + cls + ']'
                i = j + 1
        elif c == '/':
            regex += '/'
            i += 1
        else:
            regex += re.escape(c)
            i += 1

    if is_dir:
        if not path.endswith('/'):
            return False
        path = path.rstrip('/')

    if is_anchored:
        return bool(re.fullmatch(regex, path))
    else:
        return bool(re.search('(^|/)' + regex + '$', path))
