def parse_range(header, size):
    if not header:
        return None
    header = header.strip()
    if not header.startswith('bytes='):
        return None
    range_set = header[6:]
    if not range_set:
        return None
    results = []
    for part in range_set.split(','):
        part = part.strip()
        if not part:
            return None
        if part.startswith('-'):
            suffix_str = part[1:]
            if not suffix_str.isdigit():
                return None
            suffix = int(suffix_str)
            if suffix == 0:
                return None
            start = max(0, size - suffix)
            end = size - 1
        elif '-' in part:
            idx = part.index('-')
            start_str, end_str = part[:idx], part[idx+1:]
            if not start_str.isdigit():
                return None
            start = int(start_str)
            if end_str == '':
                end = size - 1
            else:
                if not end_str.isdigit():
                    return None
                end = min(int(end_str), size - 1)
            if start > end:
                continue
        else:
            return None
        results.append((start, end))
    return results if results else None
