class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.size = 0
        self.min_freq = 0
        self.val_map = {}
        self.freq_map = {}
        self.freq_to_keys = collections.defaultdict(collections.OrderedDict)

    def get(self, key):
        if self.capacity == 0 or key not in self.val_map:
            return -1
        freq = self.freq_map[key]
        del self.freq_to_keys[freq][key]
        if not self.freq_to_keys[freq]:
            del self.freq_to_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1
        self.freq_map[key] = freq + 1
        self.freq_to_keys[freq + 1][key] = None
        return self.val_map[key]

    def put(self, key, value):
        if self.capacity <= 0:
            return
        if key in self.val_map:
            self.val_map[key] = value
            freq = self.freq_map[key]
            del self.freq_to_keys[freq][key]
            if not self.freq_to_keys[freq]:
                del self.freq_to_keys[freq]
                if self.min_freq == freq:
                    self.min_freq += 1
            self.freq_map[key] = freq + 1
            self.freq_to_keys[freq + 1][key] = None
            return

        if self.size == self.capacity:
            min_freq = self.min_freq
            evict_key, _ = self.freq_to_keys[min_freq].popitem(last=False)
            del self.val_map[evict_key]
            del self.freq_map[evict_key]
            if not self.freq_to_keys[min_freq]:
                del self.freq_to_keys[min_freq]
