def evaluate(expr):
    def tokenize():
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            if expr[i].isspace():
                i += 1
                continue
            if expr[i:i+2] == '**':
                tokens.append('**')
                i += 2
            elif expr[i] in '+-*/%()':
                tokens.append(expr[i])
                i += 1
            elif expr[i].isdigit() or expr[i] == '.':
                j = i
                has_dot = False
                while j < n and (expr[j].isdigit() or expr[j] == '.'):
                    if expr[j] == '.':
                        if has_dot: raise ValueError("Invalid number format")
                        has_dot = True
                    j += 1
                num_str = expr[i:j]
                if num_str == '.':
                    raise ValueError("Invalid number format")
                tokens.append(num_str)
                i = j
            else:
                raise ValueError(f"Invalid character: {expr[i]}")
        tokens.append('END')
        return tokens

    tokens = tokenize()
    pos = [0]

    def peek():
        return tokens[pos[0]]

    def consume(expected=None):
        token = peek()
        if expected and token != expected:
            raise ValueError(f"Expected {expected}, got {token}")
        pos[0] += 1
        return token

    def parse_add_sub():
        left = parse_mul_div_mod()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_mul_div_mod()
            if op == '+': left += right
            else: left -= right
        return left

    def parse_mul_div_mod():
        left = parse_unary()
        while peek() in ('*', '/', '%'):
            op = consume()
            right = parse_unary()
            if op == '*': left *= right
            elif op == '/':
                if right == 0: raise ValueError("Division by zero")
                left /= right
            else:
                if right == 0: raise ValueError("Modulo by zero")
                left %= right
        return left

    def parse_unary():
        if peek() in ('+', '-'):
            op = consume()
            operand = parse_pow()
            if op == '-': return -operand
            return operand
        return parse_pow()

    def parse_pow():
        base = parse_primary()
        if peek() == '**':
            consume()
            exp = parse_pow()
            return base ** exp
        return base

    def parse_primary():
        token = peek()
        if token == '(':
            consume('(')
            result = parse_add_sub()
            consume(')')
            return result
        elif token == 'END':
            raise ValueError("Unexpected end of expression")
        elif token.replace('.', '', 1).isdigit():
            consume()
            return float(token) if '.' in token else int(token)
        else:
            raise ValueError(f"Unexpected token: {token}")

    result = parse_add_sub()
    if peek() != 'END':
        raise ValueError("Unexpected token after expression")
    return result
