    def clean():
        nonlocal balance
        while max_heap and -max_heap[0] in to_remove:
            val = -heapq.heappop(max_heap)
            to_remove[val] -= 1
            if to_remove[val] == 0:
                del to_remove[val]
            balance -= 1
        while min_heap and min_heap[0] in to_remove:
            val = heapq.heappop(min_heap)
            to_remove[val] -= 1
            if to_remove[val] == 0:
                del to_remove[val]
