        nonlocal balance
        clean()
        if balance > 1:
            val = -heapq.heappop(max_heap)
            heapq.heappush(min_heap, val)
            balance -= 2
        elif balance < 0:
            val = heapq.heappop(min_heap)
            heapq.heappush(max_heap, -val)
            balance += 2

    for i in range(k):
        add(a[i])
    rebalance()

    res = []
    if k % 2 == 1:
        res.append(float(-max_heap[0]))
    else:
        res.append((-max_heap[0] + min_heap[0]) / 2.0)

