class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.changes = []
        self.num_components = n

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)
        if root_a == root_b:
            return False
        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a
        self.changes.append((root_b, root_a))
        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]
        self.num_components -= 1
        return True

    def snapshot(self):
        return len(self.changes)

    def rollback(self, token):
        while len(self.changes) > token:
            root_b, root_a = self.changes.pop()
            self.parent[root_b] = root_b
            self.size[root_a] -= self.size[root_b]
            self.num_components += 1

    def components(self):
        return self.num_components
