    def __init__(self, capacity, refill_per_sec, clock):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.tokens = float(capacity)
        self.last_time = clock()

    def take(self, n=1):
        if n > self.capacity:
            return False
        if n <= 0:
            return True

