        raise ValueError("Empty string")
    base = len(alphabet)
    digit_map = {c: i for i, c in enumerate(alphabet)}
    neg = s.startswith('-')
    s = s[1:] if neg else s
    if not s:
        raise ValueError("Invalid string")
    val = 0
    for c in s:
