        }
      } else if (!isNaN(key) && key !== '') {
        if (!Array.isArray(current)) {
          current = [];
          if (parent) parent[parentKey] = current;
        }
        if (!current[key]) current[key] = {};
        current = current[key];
      } else {
        if (!current[key]) current[key] = {};
        current = current[key];
      }
    }
  }
}

function parseQuery(qs) {
  if (typeof qs !== 'string') return {};
  qs = qs.replace(/^\?/, '');
  if (!qs) return {};
  const obj = {};
  const pairs = qs.split('&');
  for (const pair of pairs) {
    if (!pair) continue;
    const eqIndex = pair.indexOf('=');
    let key, value;
    if (eqIndex === -1) {
      key = decodeURIComponent(pair.replace(/\+/g, ' '));
      value = '';
    } else {
      key = decodeURIComponent(pair.slice(0, eqIndex).replace(/\+/g, ' '));
      value = decodeURIComponent(pair.slice(eqIndex + 1).replace(/\+/g, ' '));
    }
    const path = key.replace(/\[([^\]]*)\]/g, '.$1').split('.');
    set(obj, path, value);
  }
  return obj;
}

function buildQuery(obj) {
  if (!obj || typeof obj !== 'object') return '';
  const parts = [];
  function serialize(current, prefix) {
    if (current === null || current === undefined) return;
    if (Array.isArray(current)) {
      for (let i = 0; i < current.length; i++) {
        const newPrefix = prefix ? prefix + '[' + i + ']' : String(i);
        serialize(current[i], newPrefix);
      }
    } else if (typeof current === 'object') {
      const keys = Object.keys(current).sort();
      for (const key of keys) {
        const newPrefix = prefix ? prefix + '[' + key + ']' : key;
        serialize(current[key], newPrefix);
      }
    } else {
      parts.push(encodeURIComponent(prefix) + '=' + encodeURIComponent(String(current)));
    }
  }
  serialize(obj, '');
  return parts.join('&');
}

module.exports = { parseQuery, buildQuery };
