function toposortTasks(tasks) {
  return new Promise((resolve, reject) => {
    const taskNames = Object.keys(tasks);
    const inDegree = {};
    const dependents = {};
    const results = {};
    const status = {};
    let pendingCount = taskNames.length;
    let firstError = null;
    const ready = new Set();
    let running = 0;

    for (const name of taskNames) {
      inDegree[name] = 0;
      dependents[name] = [];
      status[name] = 'pending';
    }

    for (const name of taskNames) {
      const deps = tasks[name].deps || [];
      for (const dep of deps) {
        if (!tasks[dep]) {
          return reject(new Error(`Unknown dependency: ${dep}`));
        }
        inDegree[name]++;
        dependents[dep].push(name);
      }
    }

    const visited = new Set();
    const recStack = new Set();
    function hasCycle(node) {
      visited.add(node);
      recStack.add(node);
      for (const dep of (tasks[node].deps || [])) {
        if (!visited.has(dep)) {
          if (hasCycle(dep)) return true;
        } else if (recStack.has(dep)) {
          return true;
        }
      }
      recStack.delete(node);
      return false;
    }
    for (const name of taskNames) {
      if (!visited.has(name)) {
        if (hasCycle(name)) {
          return reject(new Error("Dependency cycle detected"));
        }
      }
    }

    for (const name of taskNames) {
      if (inDegree[name] === 0) {
        ready.add(name);
      }
    }

    function processReady() {
      if (ready.size === 0 && running === 0) {
        if (pendingCount === 0) {
          if (firstError) reject(firstError);
          else resolve(results);
        } else {
          reject(new Error("Dependency cycle detected"));
        }
        return;
      }

      const batch = [...ready];
      ready.clear();

      for (const name of batch) {
        running++;
        if (status[name] === 'failed') {
          pendingCount--;
          running--;
          processReady();
          continue;
        }

        status[name] = 'running';
        const task = tasks[name];
        const depValues = {};
        for (const dep of task.deps) {
          depValues[dep] = results[dep];
        }

        task.run(depValues)
          .then(value => {
            results[name] = value;
            status[name] = 'done';
            pendingCount--;
            running--;
            for (const depName of dependents[name]) {
              if (status[depName] === 'pending') {
                inDegree[depName]--;
                if (inDegree[depName] === 0) {
                  ready.add(depName);
                }
              }
            }
            processReady();
          })
          .catch(err => {
            if (!firstError) firstError = err;
            status[name] = 'failed';
            pendingCount--;
            running--;
            function markFailed(n) {
              if (status[n] === 'pending') {
                status[n] = 'failed';
                for (const d of dependents[n]) markFailed(d);
              }
            }
            for (const depName of dependents[name]) markFailed(depName);
            for (const depName of dependents[name]) {
              if (status[depName] === 'failed') ready.add(depName);
            }
            processReady();
          });
      }
    }

    processReady();
  });
}

module.exports = toposortTasks;
