export class Bus<E extends Record<string, unknown>> {
  private handlers = new Map<string, Array<(...args: any[]) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    const list = this.handlers.get(k) || [];
    list.push(fn as any);
    this.handlers.set(k, list);
    return () => {
      const idx = list.indexOf(fn as any);
      if (idx !== -1) list.splice(idx, 1);
    };
  }

  emit<K extends keyof E>(k: K, ...args: E[K] extends void ? [] : [E[K]]): void {
    const list = this.handlers.get(k);
    if (list) {
      for (const fn of list) {
        fn(...args);
      }
    }
  }
}
