export type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T extends (...args: any[]) => any
    ? T
    : T extends readonly (infer U)[]
      ? DeepAwaited<U>[]
      : T extends object
        ? { [K in keyof T]: DeepAwaited<T[K]> }
        : T;

export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (typeof value === 'function') {
    return value as any;
  }
  if (value != null && typeof value === 'object' && 'then' in value) {
    return deepAwait(await value);
  }
  if (Array.isArray(value)) {
    return (await Promise.all(value.map(item => deepAwait(item)))) as any;
  }
  if (value != null && typeof value === 'object') {
    const keys = Object.keys(value);
    const resolved = await Promise.all(
      keys.map(async key => [key, await deepAwait((value as any)[key])])
    );
    const result: Record<string, any> = {};
    for (const [key, val] of resolved) {
      result[key] = val;
    }
    return result as any;
  }
  return value as any;
}
