type ExtractParam<S extends string> = S extends `:${infer P}` ? [P] : [];
type ParsePath<S extends string> = S extends `${infer Segment}/${infer Rest}`
  ? [...ExtractParam<Segment>, ...ParsePath<Rest>]
  : ExtractParam<Segment>;

type RouteFn<T extends string[]> = T extends []
  ? () => string
  : (params: { [K in T[number]]: string }) => string;

export function defineRoutes<R extends Record<string, string>>(
  routes: R
): { [K in keyof R]: RouteFn<ParsePath<R[K]>> } {
  const result = {} as { [K in keyof R]: RouteFn<ParsePath<R[K]>> };
  for (const key of Object.keys(routes) as (keyof R)[]) {
    const path = routes[key];
    const params = path.match(/:(\w+)/g)?.map(p => p.slice(1)) || [];
    result[key] = ((...args: any[]) => {
      const p = args[0] ?? {};
      let res = path;
      for (const param of params) {
        res = res.replace(`:${param}`, p[param] ?? '');
      }
      return res;
    }) as any;
  }
  return result;
}
