export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined) return base;
  if (patch === null) return patch as T;
  if (Array.isArray(patch)) return patch as T;
  if (typeof patch === 'function') return patch as T;
  if (typeof patch !== 'object') return patch as T;

  if (typeof base !== 'object' || base === null) return patch as T;

  const result = {} as T;
  const baseObj = base as Record<string, unknown>;
  const patchObj = patch as Record<string, unknown>;

  for (const key in baseObj) {
    if (Object.prototype.hasOwnProperty.call(baseObj, key)) {
      (result as Record<string, unknown>)[key] = baseObj[key];
    }
  }

  for (const key in patchObj) {
    if (Object.prototype.hasOwnProperty.call(patchObj, key)) {
      const pVal = patchObj[key];
      if (pVal !== undefined) {
        const bVal = baseObj[key];
        if (typeof pVal === 'object' && pVal !== null &&
            typeof bVal === 'object' && bVal !== null &&
            !Array.isArray(pVal) && !Array.isArray(bVal)) {
          (result as Record<string, unknown>)[key] = applyPatch(bVal as any, pVal as any) as any;
        } else {
          (result as Record<string, unknown>)[key] = pVal;
        }
      }
    }
  }

  return result;
}
